var n=`1255-pelau`;var t=`world-1255`;var a=`TT`;var r=`central-america-caribbean`;var o=4;var s=59;var g={en:`Pelau`,ua:`Пелау`};var l={en:`Pelau is a dish from Trinidad and Tobago featuring chicken thigh, yellow onion, garlic, green bell pepper. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Пелау, страва кухні країни Тринідад і Тобаго з такими основними складниками: куряче стегно, жовта цибуля, часник, зелений солодкий перець. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Heat the listed ingredients over moderate heat, stirring only as needed, for about 7 minutes until amber and fragrant.`,ua:`Нагрівайте зазначені складники на помірному вогні приблизно 7 хвилин до бурштинового кольору й аромату, помішуючи за потреби.`,t:[`caramelizing-sugar`],m:7,i:[[`brown-sugar`,55,`g`],[`canola-oil`,45,`ml`]]},{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 11 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 11 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:11,i:[[`chicken-thigh`,750,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`yellow-onion`,150,`g`],[`garlic`,4,`clove`],[`green-bell-pepper`,150,`g`]]},{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 30 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 30 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:30,i:[[`white-rice`,420,`g`],[`coconut-milk`,430,`ml`],[`chicken-stock`,480,`ml`],[`pigeon-peas`,300,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,30,`g`]]}];var c={slug:n,id:t,country:`TT`,region:r,servings:4,minutes:59,title:g,text:l,steps:d};export{a as country,c as default,t as id,s as minutes,r as region,o as servings,n as slug,d as steps,l as text,g as title};